contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 reserve) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(reserve > 0);
        require(address(this).balance >= reserve);

        uint256 beforeBalance = address(c).balance;
        bool reverted;

        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBalance = address(c).balance;

        assert(!reverted && afterBalance == beforeBalance);
    }

    receive() external payable {}
}

