// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 reserve) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(reserve > 0);
        vm.assume(address(this).balance >= reserve);
        uint256 beforeBalance = address(c).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBalance = address(c).balance;
        assertTrue(!reverted && afterBalance == beforeBalance);
    }

    function testFuzz_run(uint256 reserve) public {
        _run(reserve);
    }

    receive() external payable {}
}
